// One item per session: turn the transcript into a summarization prompt
return $input.all().map(i => {
  const t = i.json;
  const tz = t.business_timezone || 'Asia/Beirut';
  const started = new Date(t.session.started_at);
  const day = started.toLocaleDateString('en-CA', { timeZone: tz });
  const weekday = started.toLocaleDateString('en-US', { timeZone: tz, weekday: 'long' });
  const lines = (t.messages || []).map(m => `${m.role === 'user' ? 'Customer' : 'Assistant'}: ${m.message}`).join('\n');
  const prompt = `You write short memory notes for a business's WhatsApp assistant.
Business: ${t.business_name}
This conversation took place on ${weekday} ${day} (business local time).

Return ONLY a JSON object, no markdown, with these keys:
"summary": 3 to 6 short lines, written in the language the customer used. Include what the customer wanted; what was decided, booked or ordered (with any IDs, times); anything still unresolved. Convert EVERY relative date or time ("today", "tomorrow", "Saturday", "next week", "in two days") into an absolute date such as "Saturday 2025-03-15", computed from the conversation date above. Facts only, no greetings, never invent details. Write the summary as one string, not a list.
"name": the customer's name if stated, else null.
"language": the customer's main language as a short code (ar, fr, en, ...), else null.
"preferences": clear stated preferences or needs worth remembering (allergies, preferred times, favourite items), else null.

CONVERSATION:
${lines}`;
  return { json: { session_id: t.session.id, prompt } };
});

// Turn the model output into the /session/{id}/summary body (falls back to the raw text as the summary)
return $input.all().map(i => {
  const raw = String(i.json.text || '').replace(/<think>[\s\S]*?<\/think>/g, '').trim();
  let out = null;
  const m = raw.match(/\{[\s\S]*\}/);
  if (m) { try { out = JSON.parse(m[0]); } catch (e) { out = null; } }
  const str = v => { if (Array.isArray(v)) v = v.filter(x => typeof x === 'string').join(String.fromCharCode(10)); return (typeof v === 'string' && v.trim() ? v.trim() : null); };
  const summary = out ? str(out.summary) : (raw || null);
  return { json: {
    session_id: $('Build Summary Prompt').item.json.session_id,
    body: { summary, failed: !summary, name: out ? str(out.name) : null, language: out ? str(out.language) : null, preferences: out ? str(out.preferences) : null },
  } };
});
